// FAKE-DEMO-DATA: every byte below is generated by the test itself.
import test from 'node:test';
import assert from 'node:assert/strict';
import zlib from 'node:zlib';
import crypto from 'node:crypto';
import { inflateRaw, crc32 } from '../js/data/inflate.js';
import { listEntries, readEntry } from '../js/data/zip.js';
import { LIMITS } from '../js/data/schema.js';
import { makeZip } from './helpers/zip-writer.js';

const text = (n) => Buffer.from(Array.from({ length: n }, (_, i) => `line ${i} of some fake sample text, repeated ${i % 7}\n`).join(''));
const sameBytes = (a, b) => Buffer.compare(Buffer.from(a), Buffer.from(b)) === 0;

test('inflate matches zlib for stored, fixed, dynamic blocks, empty, random and highly repetitive data', () => {
  const inputs = [Buffer.alloc(0), Buffer.from('a'), Buffer.from('hello hello hello hello'), text(5000), crypto.randomBytes(70000), Buffer.alloc(300000, 7), Buffer.concat([text(300), crypto.randomBytes(2000), text(300)])];
  for (const input of inputs) {
    for (const level of [0, 1, 6, 9]) {
      const comp = zlib.deflateRawSync(input, { level });
      assert.ok(sameBytes(inflateRaw(comp), input), `level ${level}, ${input.length} bytes`);
    }
    const fixed = zlib.deflateRawSync(input, { strategy: zlib.constants.Z_FIXED });
    assert.ok(sameBytes(inflateRaw(fixed), input), `fixed huffman, ${input.length} bytes`);
  }
});

test('inflate rejects damaged data instead of returning garbage, and enforces the output cap', () => {
  const comp = zlib.deflateRawSync(text(2000));
  assert.throws(() => inflateRaw(comp.subarray(0, comp.length - 20)), (e) => e.code === 'parse_error');
  assert.throws(() => inflateRaw(Buffer.from([0xff, 0xff, 0xff, 0xff])), (e) => e.code === 'parse_error');
  for (let i = 0; i < 200; i++) {
    // random garbage either decodes to something or fails with OUR error type; it never crashes with a RangeError/TypeError
    try {
      inflateRaw(crypto.randomBytes(1 + (i % 400)), 1 << 20);
    } catch (e) {
      assert.ok(e.code === 'parse_error' || e.code === 'too_large', `unexpected ${e && e.name}: ${e && e.message}`);
    }
  }
  const bomb = zlib.deflateRawSync(Buffer.alloc(50 * 1024 * 1024), { level: 9 });
  const t0 = Date.now();
  assert.throws(() => inflateRaw(bomb, 1024 * 1024), (e) => e.code === 'too_large');
  assert.ok(Date.now() - t0 < 3000, 'a bomb is stopped early, not after decoding everything');
});

test('crc32 known value', () => {
  assert.equal(crc32(Buffer.from('123456789')), 0xcbf43926);
});

test('zip: list and read stored and deflated entries, names sanitised', async () => {
  const zip = makeZip([
    { name: 'DI_CONNECT/a.json', data: '{"x":1}', method: 'store' },
    { name: 'DI_CONNECT/b.json', data: text(3000) },
    { name: 'dir/', data: '', method: 'store' },
    { name: 'we‮ird\u0001.txt', data: 'x', method: 'store' },
  ]);
  const entries = await listEntries(zip);
  assert.deepEqual(entries.map((e) => e.name), ['DI_CONNECT/a.json', 'DI_CONNECT/b.json', 'dir/', 'weird.txt']);
  assert.equal(entries[2].isDir, true);
  assert.equal(Buffer.from(await readEntry(zip, entries[0])).toString(), '{"x":1}');
  assert.ok(sameBytes(await readEntry(zip, entries[1]), text(3000)));
});

test('zip: ZIP64 records and zip comments are understood', async () => {
  const zip = makeZip([{ name: 'a.json', data: '[1,2,3]' }, { name: 'b.json', data: text(100) }], { zip64: true, comment: 'a comment' });
  const entries = await listEntries(zip);
  assert.equal(entries.length, 2);
  assert.equal(Buffer.from(await readEntry(zip, entries[0])).toString(), '[1,2,3]');
  const plain = makeZip([{ name: 'a.json', data: '[1]' }], { comment: 'x'.repeat(5000) });
  assert.equal((await listEntries(plain)).length, 1);
});

test('zip: damaged files are refused with a clear error, never a crash', async () => {
  await assert.rejects(listEntries(new Uint8Array(10)), (e) => e.code === 'parse_error');
  await assert.rejects(listEntries(Buffer.from('this is not a zip file at all, just some text '.repeat(10))), (e) => e.code === 'parse_error' && /zip/i.test(e.message));
  await assert.rejects(listEntries('a string'), (e) => e.code === 'bad_format');
  const zip = makeZip([{ name: 'a.json', data: text(500) }]);
  await assert.rejects(listEntries(zip.subarray(0, zip.length - 30)), (e) => e.code === 'parse_error'); // cut off: no directory
  // flipped data byte -> checksum failure
  const entries = await listEntries(zip);
  const broken = Uint8Array.from(zip);
  broken[60] ^= 0xff;
  await assert.rejects(readEntry(broken, entries[0]), (e) => e.code === 'parse_error');
  // password protected flag
  const enc = makeZip([{ name: 'a.json', data: 'x', flags: 0x0801 }]);
  await assert.rejects(readEntry(enc, (await listEntries(enc))[0]), (e) => /password/i.test(e.message));
  // entry points outside the file
  const lying = Uint8Array.from(makeZip([{ name: 'a.json', data: 'hello' }]));
  const e0 = (await listEntries(lying))[0];
  await assert.rejects(readEntry(lying, { ...e0, offset: 10 ** 9 }), (e) => e.code === 'parse_error');
});

test('zip bombs: declared sizes over the limit are refused unread; lying small sizes cap the output', async () => {
  const big = makeZip([{ name: 'a.json', data: 'x', lieUsize: LIMITS.zipEntryBytes + 1, method: 'store' }]);
  await assert.rejects(readEntry(big, (await listEntries(big))[0]), (e) => e.code === 'too_large');
  const bomb = makeZip([{ name: 'bomb.json', data: Buffer.alloc(30 * 1024 * 1024), lieUsize: 1000, level: 9 }]);
  const t0 = Date.now();
  await assert.rejects(readEntry(bomb, (await listEntries(bomb))[0]), (e) => e.code === 'too_large');
  assert.ok(Date.now() - t0 < 3000);
  const many = makeZip(Array.from({ length: 30 }, (_, i) => ({ name: `f${i}.txt`, data: 'x', method: 'store' })));
  await assert.rejects(listEntries(many, { maxEntries: 10 }), (e) => e.code === 'too_large');
});

test('zip: the JS fallback is used when native inflate is unavailable, and gives identical bytes', async () => {
  const data = text(8000);
  const zip = makeZip([{ name: 'a.json', data }]);
  const entry = (await listEntries(zip))[0];
  const stats = {};
  const real = globalThis.DecompressionStream;
  try {
    globalThis.DecompressionStream = undefined;
    assert.ok(sameBytes(await readEntry(zip, entry, { stats }), data));
  } finally {
    globalThis.DecompressionStream = real;
  }
  assert.equal(stats.fallbackInflate, 1);
  const stats2 = {};
  assert.ok(sameBytes(await readEntry(zip, entry, { stats: stats2, forceFallback: true }), data));
  assert.equal(stats2.fallbackInflate, 1);
});
